with prev_events as (select *, lag(paid_at) over (partition by method order by paid_at, id) as prev_paid_at from payments), flagged as (select *, case when prev_paid_at is null or paid_at > prev_paid_at + interval '30' day then 1 else 0 end as new_group_flag from prev_events), sessions_payments as (select *, sum(new_group_flag) over (partition by method order by paid_at, id rows between unbounded preceding and current row) as island_id from flagged) select order_id, case when new_group_flag >= 1 then 'LARGE' else 'SMALL' end as new_group_flag_tier, count(case when status = 'FAILED' then 1 end) as failed_count, count(*) filter (where status = 'FAILED') as failed_rows, count(case when method = 'bank_transfer' then 1 end) as bank_transfer_count, count(case when status = 'FAILED' then 1 end) as failed_count_2, sum(case when method = 'card' then island_id else 0 end) as card_island_id, grouping_id() as gid from sessions_payments group by rollup (order_id, case when new_group_flag >= 1 then 'LARGE' else 'SMALL' end) having failed_count_2 > 1;
